package com.bank.market;

import java.util.logging.*;

public class ContiguousDemo {
    private static final Logger log = Logger.getLogger(ContiguousDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 1 = up day, 0 = down day for an index fund
        int[] days = {0, 1, 0, 0, 1, 1, 0};

        BalancedPeriodFinder finder = new BalancedPeriodFinder();
        int longest = finder.longestBalanced(days);

        log.info("Finding the longest stretch of equal up and down days");
        log.info("Longest balanced stretch length -> " + longest);
    }
}

