class BalancedPeriodFinder {
    // Map 0 -> -1, equal counts => running sum repeats. O(n) time, O(n) space.
    int longestBalanced(int[] nums) {
        java.util.Map<Integer, Integer> firstIndexOfSum = new java.util.HashMap<>();
        firstIndexOfSum.put(0, -1);  // seed: balanced subarray starting at index 0

        int sum = 0, best = 0;
        for (int i = 0; i < nums.length; i++) {
            sum += (nums[i] == 1) ? 1 : -1;      // transform 0 into -1
            if (firstIndexOfSum.containsKey(sum)) {
                best = Math.max(best, i - firstIndexOfSum.get(sum));  // balanced span
            } else {
                firstIndexOfSum.put(sum, i);     // store FIRST occurrence only
            }
        }
        return best;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
